 CREATE OR REPLACE FUNCTION public.updateproviderinfo(insertobj json)                                                                                                                                                                  
  RETURNS text                                                                                                                                                                                                                         
  LANGUAGE plpgsql                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                         
 declare                                                                                                                                                                                                                               
 v_providerid int;                                                                                                                                                                                                                     
 begin                                                                                                                                                                                                                                 
 v_providerid := insertobj->>'provider_id';                                                                                                                                                                                            
                                                                                                                                                                                                                                       
 update tb_provider set provider_nm = insertobj->>'provider_nm'  where provider_id =v_providerid;                                                                                                                                      
                                                                                                                                                                                                                                       
 update tb_provider_addresses set adr_city_nm = insertobj->>'adr_city_nm',adr_country_tx = insertobj->>'adr_country_tx',adr_county_cd = insertobj->>'adr_county_cd',                                                                   
 adr_street_no= (insertobj->>'adr_street_no')::int,adr_street_nm= insertobj->>'adr_street_nm',adr_zip5_no= (insertobj->>'adr_zip5_no')::int, adr_state_cd= insertobj->>'adr_state_cd',adr_county_cd_tx = insertobj->>'adr_county_cd_tx'
 where (parent_key_id)::int = v_providerid;                                                                                                                                                                                            
                                                                                                                                                                                                                                       
 return 'success';                                                                                                                                                                                                                     
                                                                                                                                                                                                                                       
 end;                                                                                                                                                                                                                                  
  $function$                                                                                                                                                                                                                           

